126	  @Override
127	  public BackgroundTaskQueue getTasks() {
128	    BackgroundTaskQueue queue = new BackgroundTaskQueue();
129	
130	    try {
131	      // We at most list a number of containers a time,
132	      // in case there are too many containers and start too many workers.
133	      // We must ensure there is no empty container in this result.
